let startOfYear = 0;
let endOfYear = 0;
const fmtAbsoluteLong = new Intl.DateTimeFormat("en-US", { dateStyle: "long", timeStyle: "short" });
const fmtAbsShortWithYear = new Intl.DateTimeFormat("en-US", { dateStyle: "medium" });
const fmtAbsShort = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" });
const formatShortDate = (date) => {
  const inst = new Date(date);
  const time = inst.getTime();
  if (isNaN(time)) {
    return "N/A";
  }
  const now = Date.now();
  if (now > endOfYear) {
    const date2 = new Date(now);
    date2.setMonth(0, 1);
    date2.setHours(0, 0, 0);
    startOfYear = date2.getTime();
    date2.setFullYear(date2.getFullYear() + 1, 0, 0);
    date2.setHours(23, 59, 59, 999);
    endOfYear = date2.getTime();
  }
  if (time >= startOfYear && time <= endOfYear) {
    return fmtAbsShort.format(inst);
  }
  return fmtAbsShortWithYear.format(inst);
};
const formatLongDate = (date) => {
  const inst = new Date(date);
  if (isNaN(inst.getTime())) {
    return "N/A";
  }
  return fmtAbsoluteLong.format(inst);
};

const FlagsNone = 0;
const FlagsNoSelf = 1 << 0;
const LABEL_MAPPING = {
  "!hide": {
    name: `Hidden by moderators`,
    flags: FlagsNoSelf
  },
  "!warn": {
    name: `Content warning`,
    flags: FlagsNoSelf
  },
  porn: {
    name: `Adult content`,
    flags: FlagsNone
  },
  sexual: {
    name: `Sexually suggestive`,
    flags: FlagsNone
  },
  "graphic-media": {
    name: `Graphic media`,
    flags: FlagsNone
  },
  nudity: {
    name: `Nudity`,
    flags: FlagsNone
  }
};
const findLabel = (labels, authorDid) => {
  if (labels?.length) {
    for (let idx = 0, len = labels.length; idx < len; idx++) {
      const label = labels[idx];
      const val = label.val;
      if (!(val in LABEL_MAPPING)) {
        continue;
      }
      const def = LABEL_MAPPING[val];
      if (def.flags & FlagsNoSelf && label.src === authorDid) {
        continue;
      }
      return def;
    }
  }
};

const long = new Intl.NumberFormat("en-US");
const compact = new Intl.NumberFormat("en-US", { notation: "compact" });
const formatCompactNumber = (value) => {
  if (value < 1e3) {
    return "" + value;
  }
  if (value < 1e5) {
    return long.format(value);
  }
  return compact.format(value);
};
const formatLongNumber = (value) => {
  return long.format(value);
};

const AT_URI_RE = /^at:\/\/((?:did:[a-zA-Z0-9._:%-]+)|(?:[a-zA-Z0-9][a-zA-Z0-9-.]*))(?:\/([a-zA-Z0-9.-]+)(?:\/([a-zA-Z0-9_~.:-]{1,512}))?)?\/?(?:\?([^#\s]*))?(?:#([^\s]*))?$/;
const parseAtUri = (str) => {
  const match = AT_URI_RE.exec(str);
  if (!match) {
    throw new InvalidAtUriError(`invalid at-uri: ${str}`);
  }
  return {
    repo: match[1],
    collection: match[2] ?? "",
    rkey: match[3] ?? "",
    query: match[4] ?? "",
    fragment: match[5] ?? ""
  };
};
class InvalidAtUriError extends Error {
}

