const safeParseUrl = (str) => {
	let url;

	if ('parse' in URL) {
		url = URL.parse(str);
	} else {
		try {
			// @ts-expect-error: `'parse' in URL` is giving truthy
			url = new URL(str);
		} catch {}
	}

	if (url && (url.protocol === 'https:' || url.protocol === 'http:')) {
		return url;
	}

	return null;
};

